#!/usr/bin/env bash
# fm-jev-gate-resolver.sh - Jev No-Mistakes Gate Review Finding Classifier & Resolution Generator
#
# Usage:
#   fm-jev-gate-resolver.sh [findings_file] [--json] [--resolve-cmds] [--child <child>] [--key <key>]
#
# Parses structured review findings generated by the no-mistakes gate pipeline,
# classifies findings into auto-fixable, pre-authorized, and policy categories,
# and generates canonical fm-send resolution commands.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PYTHON_BIN="$(command -v python3 || command -v python || true)"

if [[ -z "$PYTHON_BIN" ]]; then
  echo "Error: Python 3 interpreter required for fm-jev-gate-resolver." >&2
  exit 1
fi

exec "$PYTHON_BIN" "$SCRIPT_DIR/fm-jev-gate-resolver.py" "$@"
